<x-hris.table id="certificates-table" endpoint="/cert/data" search :columns="[['key'=>'snapshot.name','label'=>'Employee'],['key'=>'type','label'=>'Type'],['key'=>'purpose','label'=>'Purpose'],['key'=>'status','label'=>'Status']]" :actions="auth()->user()->hasAbility('certificates.manage') ? [['name'=>'details','label'=>'Details / files'],['name'=>'process','label'=>'HR action'],['name'=>'complete','label'=>'Upload completed PDF'],['name'=>'print','label'=>'Print record']] : [['name'=>'details','label'=>'Details / files'],['name'=>'print','label'=>'Print record']]"/>
<x-hris.modal id="certificate-request" title="Request employment certificate"><form id="certificate-request-form" data-endpoint="/cert"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none"></div><div class="row g-3"><x-hris.field name="type" type="select" :options="auth()->user()->hasAbility('certificates.manage') ? ['current'=>'My current employment','manual'=>'Former employee'] : ['current'=>'My current employment']" value="current" required/>
@if(auth()->user()->hasAbility('certificates.manage'))<x-hris.field name="employee_id" label="Former employee (manual certificates only)" type="select" :options="$formerEmployees->pluck('name','id')->all()"/>@endif
<x-hris.field name="purpose" type="textarea" class="col-12" required/></div></div><div class="modal-footer"><button class="btn btn-primary">Submit request</button></div></form></x-hris.modal>
@if(auth()->user()->hasAbility('certificates.manage'))
<x-hris.modal id="certificate-action" title="Certificate processing"><form id="certificate-action-form"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none"></div><div class="row g-3"><x-hris.field name="action" type="select" :options="['receive'=>'Receive','acknowledge'=>'Acknowledge','approve'=>'Approve','reject'=>'Reject','generate'=>'Record issuance']" required/><x-hris.field name="reason" type="textarea"/><div class="col-12"><p class="form-text">Compensation inputs are annual amounts. Issuance requires a configured approved signer. Upload the approved PDF after recording issuance.</p></div>@foreach($amountFields as $field)<x-hris.field :name="$field" type="number" min="0" max="999999999.99" step="0.01" value="0"/>@endforeach</div></div><div class="modal-footer"><button class="btn btn-primary">Record action</button></div></form></x-hris.modal>
<x-hris.modal id="certificate-complete" title="Upload completed certificate"><form id="certificate-complete-form" enctype="multipart/form-data"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none"></div><x-hris.field name="file" type="file" accept=".pdf" required/></div><div class="modal-footer"><button class="btn btn-primary">Complete certificate</button></div></form></x-hris.modal>
@endif
<x-hris.modal id="certificate-details" title="Certificate details"><div class="modal-body"><div id="certificate-info" style="white-space:pre-line"></div><div id="certificate-files" class="vstack gap-2"></div></div></x-hris.modal>
@endsection
@push('scripts')<script>document.addEventListener('hris:ready',()=>{const table=document.querySelector('#certificates-table');for(const id of ['certificate-request-form','certificate-action-form','certificate-complete-form']){const form=document.getElementById(id);if(form)HRIS.bindForm(form,{success:()=>table.table.load()})}table.addEventListener('table:action',({detail:{action,row}})=>{if(action==='print'){window.open(`/cert/${row.id}/print`,'_blank','noopener');return}if(action==='details'){document.querySelector('#certificate-info').textContent=`${row.snapshot.name} · ${row.status} · ${row.purpose}\n${(row.history||[]).map(entry=>`${entry.status} — ${entry.actor?.name||"Recorded actor"}${entry.reason?`: ${entry.reason}`:""}`).join("\n")}`;const files=document.querySelector('#certificate-files');files.replaceChildren();for(const file of row.files||[]){const link=document.createElement('a');link.href=`/files/${file.private_file_id}`;link.textContent='Download completed PDF';files.append(link)}HRIS.openModal('certificate-details');return}const id=action==='complete'?'certificate-complete':'certificate-action',form=document.querySelector(`#${id}-form`);HRIS.fillForm(form,{});form.dataset.endpoint=`/cert/${row.id}/${action==='complete'?'complete':'transition'}`;HRIS.openModal(id)})});</script>@endpush
